    fact_j = 1
    for j in range(1, k + 1):
        if j > 1:
            fact_j *= j

        # Calculate j^(n-1)
        if n == 1:
            j_pow_n_minus_1 = 1
        else:
            j_pow_n_minus_1 = j**(n - 1)

        term = fact_j * j_pow_n_minus_1
        total_sum += term

    return total_sum

