import math

def R_prime_k(k, n):
    """Calculates R'_k(n) = k! * sum_{j=1}^k (j^(n-1) / j!)"""
    if n <= 0:
        raise ValueError("n must be a positive integer")

    sum_fractional = 0

    for j in range(1, k + 1):
        # j^(n-1)
        if n == 1:
            j_pow_n_minus_1 = 1
        else:
            j_pow_n_minus_1 = j**(n - 1)

        # j!
        fact_j = math.factorial(j)

        sum_fractional += j_pow_n_minus_1 / fact_j

    R_prime = math.factorial(k) * sum_fractional
    return R_prime

def check_constraints_prime(n):
    k_values = [2, 3, 4, 5]
    residues = {}

    for k in k_values:
        k_factorial = math.factorial(k)
        R_prime_k_n = R_prime_k(k, n)

        # Required constraint: a = -R'_k(n) mod k!
        # We must ensure integer results for the congruence.
        # R'_k(n) must be an integer for the congruence to hold meaningfully, 
        # otherwise we deal with fractions mod k!, which is complex.
        # Since the premise is that {a_k} consists ONLY of integers, R'_k(n) must be an integer.

        if abs(R_prime_k_n - round(R_prime_k_n)) > 1e-9:
             return f"ERROR: R'_{k}({n}) is not an integer ({R_prime_k_n}). Constraint cannot be formulated.", {}

        R_prime_k_n_int = int(round(R_prime_k_n))
        C_k_n = (-R_prime_k_n_int) % k_factorial
        residues[k] = C_k_n

    return "Success", residues

